import { useQuery } from '@tanstack/react-query';
import { currentAsOf, getJson, getLiveJson } from '../../api/http';
import { useClaims } from '../claims/claims';
import type { Claim } from '../claims/claims';
import { usePeople } from '../people/people';
import type { Person } from '../people/people';
import { total, useRates } from '../rates/rates';
import type { Rate } from '../rates/rates';
import { sheetKey, useCurrentSheet } from '../session/session';
import type { SheetInfo } from '../session/session';
import { dueRules, useDueRules } from '../settings/settings';
import type { Settings } from '../settings/settings';
import { sheetTotals } from './HeaderCounters';

/** One sheet's figures: how many people, its due-total and overdue-total as that sheet shows them. */
type Figures = { people: number; due: string; overdue: string };

/** The query key for the figures of the sheet's descendants; under sheetKey, so re-loading the sheet re-reads them. */
export const descendantFiguresKey = (sheet: string) => [...sheetKey(sheet), 'descendant-figures'] as const;

/**
 * A sheet's figures, worked out from what the store holds for it now by its own today and rules; while the screen
 * shows a date, as the sheet stood at the end of that day, with that date as its today.
 */
async function figuresOf(sheet: string): Promise<Figures> {
  const path = `/api/sheets/${encodeURIComponent(sheet)}`;
  const [info, people, claims, rates, settings] = await Promise.all([
    getJson<SheetInfo>(path),
    getJson<Person[]>(`${path}/people`),
    getJson<Claim[]>(`${path}/claims`),
    getJson<Rate[]>(`${path}/rates`),
    getJson<Settings>(`${path}/settings`),
  ]);
  return { people: people.length, ...sheetTotals(people, claims, rates, dueRules(settings, info.today, claims)) };
}

/**
 * The figures of each of the sheet's descendants (its children, theirs and so on), as they stand now, or as they
 * stood at the end of the date the screen shows.
 */
function useStoredFigures(asOf: string) {
  const [sheet] = useCurrentSheet();
  return useQuery({
    queryKey: [...descendantFiguresKey(sheet), asOf],
    queryFn: async () => {
      const ids = await getLiveJson<string[]>(`/api/sheets/${encodeURIComponent(sheet)}/descendants`);
      return Promise.all(ids.map(figuresOf));
    },
    enabled: !!sheet,
  });
}

// The consolidated figures over the sheet and all its descendants: the people counted, and each sheet's
// due-total and overdue-total as that sheet shows them, added up. A sheet with no children shows its own. While the
// screen shows the sheet as of a date, every sheet of the tree is taken as it stood at the end of that day.
export function ConsolidatedFigures() {
  const asOf = currentAsOf();
  const people = usePeople().data ?? [];
  const claims = useClaims().data ?? [];
  const rates = useRates().data ?? [];
  const rules = useDueRules();
  const stored = useStoredFigures(asOf).data ?? [];

  const all: Figures[] = [{ people: people.length, ...sheetTotals(people, claims, rates, rules) }, ...stored];
  return (
    <p data-testid="consolidated-figures">
      Consolidated — People: <strong data-testid="consolidated-people-count">{all.reduce((n, f) => n + f.people, 0)}</strong>
      {' · '}Due: <strong data-testid="consolidated-due-total">{total(all.map((f) => f.due))}</strong>
      {' · '}Overdue: <strong data-testid="consolidated-overdue-total">{total(all.map((f) => f.overdue))}</strong>
    </p>
  );
}
import { AppHeader } from '../../slots/defs/appHeader';
import { ConsolidatedFigures } from './ConsolidatedFigures';

export const contribution = AppHeader.fill({ order: 31, Component: ConsolidatedFigures });
import { useAliases } from '../aliases/aliases';
import type { Alias } from '../aliases/aliases';
import { useClaims } from '../claims/claims';
import { crewDue, useCrews, useDueByPerson } from '../crews/crews';
import type { Claim } from '../claims/claims';
import { personOverdue } from '../overdue/overdue';
import { liveHolds, usePeople } from '../people/people';
import type { Person } from '../people/people';
import { personDue, total, trimmedTotal, useRates } from '../rates/rates';
import type { Rate } from '../rates/rates';
import { useDueRules } from '../settings/settings';
import type { DueRules } from '../settings/settings';
import { useCurrentUser } from '../session/session';

/** The statuses counted, as in the summary; one no claim reaches yet still shows, as 0. */
const STATUSES = ['DRAFT', 'OPEN', 'PENDING', 'SETTLED', 'VOID', 'REVIEW'] as const;

/** A sheet's due-total and overdue-total as its header shows them. */
export function sheetTotals(people: Person[], claims: Claim[], rates: Rate[], rules: DueRules): { due: string; overdue: string } {
  const mine = (id: number) => claims.filter((c) => c.personId === id);
  const dues = people.map((p) => personDue(mine(p.id), rates, p.grades, liveHolds(p, rules.today), rules));
  const overdue = people.map((p) => personOverdue(mine(p.id), rates, p.grades, liveHolds(p, rules.today), rules).total);
  return { due: trimmedTotal(dues), overdue: trimmedTotal(overdue) };
}

/** A name as names are compared: trimmed, ignoring case. */
const nameKey = (name: string) => name.trim().toLowerCase();

/** The person on the sheet with the user's name, by name or alias, if any. */
export function personNamed(people: Person[], aliases: Alias[], user: string): Person | undefined {
  const key = nameKey(user);
  if (!key) return undefined;
  return (
    people.find((p) => nameKey(p.name) === key) ??
    people.find((p) => aliases.some((a) => a.personId === p.id && nameKey(a.alias) === key))
  );
}

// The sheet's counters, always in the header: everyone on it (retired people included), its claims per
// status, its due-total and overdue-total, the signed-in user's own (blank when no one on it has their name), and the due-totals of the crews that person
// leads added up (blank when they lead none) — each worked out exactly as the figure it repeats.
export function HeaderCounters() {
  const people = usePeople().data ?? [];
  const claims = useClaims().data ?? [];
  const rates = useRates().data ?? [];
  const rules = useDueRules();
  const aliases = useAliases().data ?? [];
  const crews = useCrews().data ?? [];
  const dueOf = useDueByPerson();
  const [user] = useCurrentUser();

  const me = personNamed(people, aliases, user ?? '');
  const mine = me ? claims.filter((c) => c.personId === me.id) : [];
  const myDue = me ? personDue(mine, rates, me.grades, liveHolds(me, rules.today), rules) : '';
  const myOverdue = me ? personOverdue(mine, rates, me.grades, liveHolds(me, rules.today), rules).total : '';
  const led = me ? crews.filter((c) => c.lead?.id === me.id) : [];
  const myCrewDue = led.length ? total(led.map((c) => crewDue(c, dueOf))) : '';
  const totals = sheetTotals(people, claims, rates, rules);
  return (
    <p data-testid="header-counters">
      People: <strong data-testid="header-people-count">{people.length}</strong>
      {STATUSES.map((s) => (
        <span key={s}>
          {' · '}
          {s}: <strong data-testid={`header-claims-${s}-count`}>{claims.filter((c) => c.status === s).length}</strong>
        </span>
      ))}
      {' · '}Due: <strong data-testid="header-due-total">{totals.due}</strong>
      {' · '}Overdue: <strong data-testid="header-overdue-total">{totals.overdue}</strong>
      {' · '}Mine: <strong data-testid="my-due-total">{myDue}</strong>
      {' / '}<strong data-testid="my-overdue-total">{myOverdue}</strong>
      {' · '}My crews: <strong data-testid="my-crew-due-total">{myCrewDue}</strong>
    </p>
  );
}
import { AppHeader } from '../../slots/defs/appHeader';
import { HeaderCounters } from './HeaderCounters';

export const contribution = AppHeader.fill({ order: 30, Component: HeaderCounters });
import { isActive } from '../active/active';
import { useClaims } from '../claims/claims';
import { GRADES, liveHolds, usePeople } from '../people/people';
import { periodDue, usePeriods } from '../periods/periods';
import { personDue, total, useRates } from '../rates/rates';
import { useCurrentSheet, useCurrentUser } from '../session/session';
import { useDueRules, useSettings } from '../settings/settings';
import { reviewLate } from '../reviewlate/reviewLate';
import { useVoidReasons } from '../voidreasons/voidReasons';

/** The statuses the summary counts claims by; one no claim reaches yet still shows, as 0. */
const STATUSES = ['DRAFT', 'OPEN', 'PENDING', 'SETTLED', 'VOID', 'REVIEW'] as const;

// The sheet at a glance, worked out from the same figures the list shows. Per grade: the people on it
// today (retired people left out), their due-totals added up (skipping n/a) and how many of them are active. Per period: its
// due-total and its change from the period before it by start date (none for the earliest). Per status: how many claims have it, and how many REVIEW claims are late past the review SLA. Per void reason on the list: how many VOID claims were voided with it.
export function Summary() {
  const [user] = useCurrentUser();
  const [sheet] = useCurrentSheet();
  const people = usePeople().data ?? [];
  const claims = useClaims().data ?? [];
  const periods = usePeriods().data ?? [];
  const rates = useRates().data ?? [];
  const rules = useDueRules();
  const voidReasons = useVoidReasons().data ?? [];
  const reviewSla = useSettings().data?.reviewSla ?? '';

  if (!user || !sheet) return null;

  const current = people.filter((p) => !p.retired);
  const periodDues = new Map(periods.map((p) => [p.name, periodDue(p, claims, people, rates, rules)]));
  const byStart = [...periods].sort((a, b) => a.from.localeCompare(b.from));
  const periodChange = new Map(
    byStart.map((p, i) => [
      p.name,
      i === 0 ? '' : (cents(periodDues.get(p.name)!) - cents(periodDues.get(byStart[i - 1].name)!)) / 100,
    ]),
  );
  return (
    <section data-testid="summary">
      <table>
        <thead>
          <tr>
            <th>Grade</th>
            <th>People</th>
            <th>Due total</th>
            <th>Active</th>
          </tr>
        </thead>
        <tbody>
          {GRADES.map((g) => {
            const on = current.filter((p) => p.grade === g);
            const dues = on.map((p) =>
              personDue(claims.filter((c) => c.personId === p.id), rates, p.grades, liveHolds(p, rules.today), rules),
            );
            return (
              <tr key={g}>
                <td>{g}</td>
                <td data-testid={`summary-grade-${g}-count`}>{on.length}</td>
                <td data-testid={`summary-grade-${g}-due-total`}>{total(dues)}</td>
                <td data-testid={`summary-grade-${g}-active`}>
                  {on.filter((p) => isActive(claims.filter((c) => c.personId === p.id), liveHolds(p, rules.today), rules.today)).length}
                </td>
              </tr>
            );
          })}
        </tbody>
      </table>
      <table>
        <thead>
          <tr>
            <th>Period</th>
            <th>Due total</th>
            <th>Change</th>
          </tr>
        </thead>
        <tbody>
          {periods.map((p) => (
            <tr key={p.name}>
              <td>{p.name}</td>
              <td data-testid={`summary-period-${p.name}-due-total`}>{periodDues.get(p.name)}</td>
              <td data-testid={`summary-period-${p.name}-change`}>{formatChange(periodChange.get(p.name))}</td>
            </tr>
          ))}
        </tbody>
      </table>
      <table>
        <thead>
          <tr>
            <th>Status</th>
            <th>Claims</th>
          </tr>
        </thead>
        <tbody>
          {STATUSES.map((s) => (
            <tr key={s}>
              <td>{s}</td>
              <td data-testid={`summary-status-${s}-count`}>{claims.filter((c) => c.status === s).length}</td>
            </tr>
          ))}
          <tr>
            <td>REVIEW late</td>
            <td data-testid="summary-review-late-count">
              {claims.filter((c) => reviewLate(c, reviewSla, rules.today)).length}
            </td>
          </tr>
        </tbody>
      </table>
      <table>
        <thead>
          <tr>
            <th>Void reason</th>
            <th>Claims</th>
          </tr>
        </thead>
        <tbody>
          {voidReasons.map((r) => (
            <tr key={r}>
              <td>{r}</td>
              <td data-testid={`summary-void-${r}-count`}>
                {claims.filter((c) => c.status === 'VOID' && c.voidReason === r).length}
              </td>
            </tr>
          ))}
        </tbody>
      </table>
    </section>
  );
}

/** A two-decimal value as whole hundredths, exactly. */
const cents = (value: string) => Math.round(Number(value) * 100);

/** A change in due-total, two decimals with a minus sign when lower; nothing for the earliest period. */
function formatChange(change: number | string | undefined): string {
  return typeof change === 'number' ? (change === 0 ? '0.00' : change.toFixed(2)) : '';
}
import { HomeMain } from '../../slots/defs/homeMain';
import { ClassicSummary } from './ClassicSummary';
import { Summary } from './Summary';

export const contributions = [
  HomeMain.fill({ order: 50, Component: Summary }),
  HomeMain.fill({ order: 51, Component: ClassicSummary }),
];
